using System;using Ashfall.Core;using Ashfall.Integration.Playable.HandsWeapons;
static class Cases
{
 static int count;static void Check(bool b,string m){count++;if(!b)throw new Exception(m);}static bool Near(float a,float b){return Math.Abs(a-b)<.000001;}
 static Float3 Sub(Float3 a,Float3 b){return R23WeaponPoseMath.Add(a,R23WeaponPoseMath.Scale(b,-1));}
 static void Geometry(R24RescueTrainingDummyGeometry data){Check(data.Positions.Length==data.Normals.Length&&data.Indices.Length%3==0,"complete geometry");for(int i=0;i<data.Indices.Length;i+=3){int a=data.Indices[i],b=data.Indices[i+1],c=data.Indices[i+2];var normal=R23WeaponPoseMath.Cross(Sub(data.Positions[b],data.Positions[a]),Sub(data.Positions[c],data.Positions[a]));Check(R23WeaponPoseMath.Dot(normal,data.Normals[a])>0,"positive winding/nonzero triangles");}foreach(var n in data.Normals)Check(Math.Abs(R23WeaponPoseMath.Dot(n,n)-1)<.000001,"unit source normals");}
 static void Main(){var s=new R24RescueTrainingDummyState();Check(s.Downed&&s.Health==0&&s.ReviveCount==0&&s.ResetRemaining==0,"source initial downed");Check(s.Readout=="RESCUE TRAINING\nDOWNED","exact downed caption");
 Check(!s.TryRevive("someone",true)&&!s.TryRevive(R24RescueTrainingDummyState.TargetId,false),"wrong/hidden targets refused");
 var p=new R23ShotPose(new Float3(10,2,-600),new Float3(1,0,0),new Float3(0,1,0),new Float3(0,0,1));R24ReviveTarget target;Check(s.TryReadTarget(p,true,out target)&&Near(target.LeftPad.X,9.87f)&&Near(target.LeftPad.Y,2.61f)&&Near(target.LeftPad.Z,-600.13f),"actual target type and once-reflected source contacts");
 Check(!s.TryReadTarget(p,false,out target),"hidden target omitted");s.TryReadTarget(p,true,out target);
 var paddles=new R24RevivePaddlesState();paddles.Equip();for(int i=0;i<230&&!paddles.Ready;i++)paddles.Step(.05f,true,false,new Float3(-.13f,.61f,.13f),new Float3(.13f,.61f,.13f),new Float3(1,0,0),new Float3(-1,0,0));Check(paddles.Ready,"actual source paddles charge without bypass");
 var probe=new R24RescueTrainingDummyState();R24ReviveTarget probeTarget;probe.TryReadTarget(p,true,out probeTarget);var outward=new Float3(0,0,-.4f);var behind=new Float3(0,0,.2f);Func<Float3,Float3,bool> clear=delegate(Float3 a,Float3 b){return true;};Func<string,bool> actualComplete=delegate(string id){return probe.TryRevive(id,true);};
 Check(paddles.TryRevive(R23WeaponPoseMath.Add(probeTarget.LeftPad,outward),R23WeaponPoseMath.Add(probeTarget.RightPad,outward),probeTarget,clear,actualComplete)&&probe.ReviveCount==1,"source chest-front .4 accepts through existing reflected Contact contract");probe.ResetTraining();
 Check(paddles.TryRevive(R23WeaponPoseMath.Add(probeTarget.RightPad,outward),R23WeaponPoseMath.Add(probeTarget.LeftPad,outward),probeTarget,clear,actualComplete)&&probe.ReviveCount==2,"source front .4 swapped pad order accepts");probe.ResetTraining();
 Check(!paddles.TryRevive(R23WeaponPoseMath.Add(probeTarget.LeftPad,behind),R23WeaponPoseMath.Add(probeTarget.RightPad,behind),probeTarget,clear,actualComplete)&&probe.ReviveCount==2,"source chest-back .2 rejects without completing");
 Check(!paddles.TryRevive(R23WeaponPoseMath.Add(probeTarget.RightPad,behind),R23WeaponPoseMath.Add(probeTarget.LeftPad,behind),probeTarget,clear,actualComplete)&&probe.ReviveCount==2,"source back .2 swapped order rejects");
 Check(paddles.TryRevive(target.LeftPad,target.RightPad,target,delegate(Float3 a,Float3 b){return true;},delegate(string id){return s.TryRevive(id,true);}),"actual paddle callback completes only genuine dummy");
 Check(!s.Downed&&s.Health==50&&s.ReviveCount==1&&s.ResetRemaining==12,"source50health count and12second timer");Check(s.Readout=="RESCUE COMPLETE\nTraining resets in 12 seconds","exact complete caption");Check(!s.TryReadTarget(p,true,out target)&&!s.TryRevive(R24RescueTrainingDummyState.TargetId,true),"completed dummy not revivable");
 s.Tick(-1);Check(s.ResetRemaining==12,"negative source dt clamps0");s.Tick(11.5f,true);Check(!s.Downed&&s.ResetRemaining==.5f,"ordinary main menu pause does not freeze child process");s.Tick(.5f,true);Check(s.Downed&&s.Health==0&&s.ReviveCount==1&&s.ResetRemaining==0,"exact12s resets health but preserves count");s.Tick(30);Check(s.ReviveCount==1,"downed no early repeated reset");
 s.TryRevive(R24RescueTrainingDummyState.TargetId,true);s.ResetTraining();Check(s.Downed&&s.ReviveCount==2&&s.ResetRemaining==0,"true checkpoint reset preserves lifetime count");
 Check(R24RescueTrainingDummyState.CheckpointOffset(true).Y==.45f&&R24RescueTrainingDummyState.CheckpointOffset(false).Y==-1&&R24RescueTrainingDummyState.CheckpointOffset(false).Z==3,"exact sandbox/other checkpoint offsets reflected once");
 Geometry(R24RescueTrainingDummyGeometry.Body());Geometry(R24RescueTrainingDummyGeometry.Pad());Console.WriteLine("PASS "+count+" source dummy lifecycle/actual paddle callback/geometry cases; no native or renderer execution");}
}
